#include <stdio.h>
void merge(int *a, int lo, int mid, int hi) {
    int t[64], i = lo, j = mid + 1, k = 0;
    while (i <= mid && j <= hi) t[k++] = a[i] <= a[j] ? a[i++] : a[j++];
    while (i <= mid) t[k++] = a[i++];
    while (j <= hi) t[k++] = a[j++];
    for (i = lo, k = 0; i <= hi; i++, k++) a[i] = t[k];
}
void msort(int *a, int lo, int hi) {
    if (lo >= hi) return;
    int mid = lo + (hi - lo) / 2;
    msort(a, lo, mid); msort(a, mid + 1, hi); merge(a, lo, mid, hi);
}
int main(void) {
    int a[] = {5, 2, 9, 1, 7};
    msort(a, 0, 4);
    for (int i = 0; i < 5; i++) printf("%d ", a[i]);
    printf("\n");
    return 0;
}

